import { computed } from 'vue'
import ChoicesEditor from '@/components/admin/ChoicesEditor.vue'
import { useChoicesStore } from '@/stores/choices'
import {
  getRealmTierTemplateList,
  getRealmTierTemplate,
} from '@/data/presetChoicesTemplates'

const choices = useChoicesStore()

const items = computed(() => choices.realmTiers)

/** 只读保护：数据库枚举值（修改后已有数据会丢失显示） */
const readOnlyKeys = ['mortal', 'spirit', 'heaven', 'sage']

/** 模板列表（下拉） */
const templates = computed(() => getRealmTierTemplateList())

/** 根据模板 key 获取模板内容数组（传给 ChoicesEditor） */
function getTemplateFn(key) {
  return getRealmTierTemplate(key)
}

function onSave(list) {
  choices.realmTiers.splice(0, choices.realmTiers.length, ...list)
}
